<?php
namespace App\Models;
use App\Models\Concerns\InvalidatesCaseStudies; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};
class CaseStudy extends Model { use HasFactory,InvalidatesCaseStudies; protected $fillable=['client_id','testimonial_id','title','slug','eyebrow','short_description','challenge','solution','outcome','featured_image_path','featured_image_alt','project_date','project_duration_text','location_text','status','is_featured','display_order','published_at','scheduled_for','archived_at','primary_cta_label','primary_cta_url','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by']; protected function casts():array{return ['project_date'=>'date','is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function client():BelongsTo{return $this->belongsTo(Client::class);} public function testimonial():BelongsTo{return $this->belongsTo(Testimonial::class);} public function metrics():HasMany{return $this->hasMany(CaseStudyMetric::class)->orderBy('display_order');} public function highlights():HasMany{return $this->hasMany(CaseStudyHighlight::class)->orderBy('display_order');} public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'case_study_solution_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'case_study_product_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedIndustries():BelongsToMany{return $this->belongsToMany(Industry::class,'case_study_industry_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedCapabilities():BelongsToMany{return $this->belongsToMany(Capability::class,'case_study_capability_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'case_study_page_relations')->withPivot('display_order')->orderByPivot('display_order');} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
